/**
 * Verify bundled example netlists with eecircuit-engine
 * Run: node scripts/verify-examples.mjs
 */
import { Simulation } from 'eecircuit-engine';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const examplesDir = path.join(__dirname, '..', 'src', 'examples');

const examples = [
  'rc-lowpass.net',
  'rl.net',
  'rlc-ringing.net',
  'diode-rectifier.net',
  'bjt-common-emitter.net',
  'opamp-inverting.net',
];

async function verifyExample(filename) {
  const filepath = path.join(examplesDir, filename);
  if (!fs.existsSync(filepath)) {
    console.error(`❌ ${filename}: File not found`);
    return false;
  }

  const netlist = fs.readFileSync(filepath, 'utf-8');
  const sim = new Simulation();
  const t0 = Date.now();

  try {
    await sim.start();
    sim.setNetList(netlist);
    const result = await sim.runSim();
    const elapsed = Date.now() - t0;

    console.log(`✓ ${filename}`);
    console.log(
      `  → ${result.numPoints} points, ${result.numVariables} variables, ${elapsed}ms`,
    );
    return true;
  } catch (err) {
    console.error(`❌ ${filename}: ${err.message}`);
    return false;
  }
}

async function main() {
  console.log('Verifying example netlists...\n');
  const results = await Promise.all(examples.map((e) => verifyExample(e)));
  const passed = results.filter(Boolean).length;
  console.log(`\n${passed}/${results.length} examples verified.`);
  process.exit(passed === results.length ? 0 : 1);
}

main();

