rawInput.text:
/**
 * Circuit Séance — CRT aesthetic stylesheet
 * Phosphor green, haunted vibes, Share Tech Mono / VT323 fonts
 */

:root {
  /* CRT colour palette */
  --crt-bg: #0a0f0a;
  --crt-phosphor-green: #39ff14;
  --crt-phosphor-yellow: #aaff44;
  --crt-phosphor-blue: #88ccff;
  --crt-phosphor-white: #cccccc;
  --crt-graticule: #1a3a1a;
  --crt-border: #2a4a2a;

  /* Typography */
  --font-mono: 'Share Tech Mono', 'VT323', monospace;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.5rem;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;

  /* Border radius */
  --radius-sm: 2px;
  --radius-md: 4px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-normal: 300ms ease;

  @media (prefers-reduced-motion: reduce) {
    --transition-fast: 0s;
    --transition-normal: 0s;
  }
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  background-color: var(--crt-bg);
  color: var(--crt-phosphor-green);
  font-family: var(--font-mono);
  font-size: var(--font-size-base);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Utility classes */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.phosphor-glow {
  text-shadow: 0 0 8px var(--crt-phosphor-green), 0 0 16px rgba(57, 255, 20, 0.3);
}

.phosphor-border {
  border: 1px solid var(--crt-phosphor-green);
  box-shadow: inset 0 0 8px rgba(57, 255, 20, 0.1);
}

@media (prefers-reduced-motion: no-preference) {
  @keyframes flicker {
    0% {
      opacity: 1;
    }
    2% {
      opacity: 0.98;
    }
    4% {
      opacity: 1;
    }
    6% {
      opacity: 0.97;
    }
    8% {
      opacity: 1;
    }
    100% {
      opacity: 1;
    }
  }

  .flicker {
    animation: flicker 0.15s infinite;
  }
}

/* Accessibility */
:focus-visible {
  outline: 2px solid var(--crt-phosphor-green);
  outline-offset: 2px;
}

/* Responsive breakpoints */
@media (max-width: 1023px) {
  :root {
    --font-size-sm: 0.8125rem;
  }
}

@media (max-width: 767px) {
  :root {
    --font-size-sm: 0.75rem;
    --space-md: 0.75rem;
    --space-lg: 1rem;
  }
}

